    pub fn dispose(self: *Runtime, diagnostic: ?*diagnostics.Diagnostic) status.Error!void {
        if (self.closed) return;
        try call.invoke("mln_runtime_dispose", .handle, self.*, null, diagnostic, .{});
        self.closed = true;
