    }

    /// Adds headers to the runtime's HTTP requests.
    ///
    /// The transform replaces the one set before. In a browser or on OpenHarmony,
    /// serve the requests with `Runtime.setResourceProvider()` instead.
    ///
    /// Runs on a library thread.
