/// A parsed style expression.
///
/// See `mln_style_expression` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/base_8h.html).
pub const StyleExpression = struct {
    raw: u64,
    closed: bool = false,
    pub const native_name = "mln_style_expression";
    const methods = owner.Handle(@This(), "StyleExpression", struct {
        fn dispose(raw: u64) status.Error!void {
            c.mln_style_expression_release(raw);
        }
    }.dispose);
    pub const adopt = methods.adopt;
    pub const id = methods.id;
    pub const isClosed = methods.isClosed;
    pub const format = methods.format;
    pub const deinit = methods.deinit;
    /// Parses a style
    /// \[expression\](https://maplibre.org/maplibre-style-spec/expressions/) to
    /// evaluate without a map.
    ///
    /// See `mln_style_expression_create` in the
    /// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/style__expression_8h.html).
    ///
    /// Errors:
    ///
    /// - `error.InvalidArgument` when `expression` isn't a valid expression, or its
    ///   result can't have the expected type.
    pub fn create(expression: []const u8, options: ?StyleExpressionOptions, diagnostic: ?*diagnostics.Diagnostic) status.Error!StyleExpression {
        return call.invoke("mln_style_expression_create", .none, {}, null, diagnostic, .{ expression, options, call.adopt(StyleExpression) });
    }

    /// Evaluates a style expression and writes its result as JSON.
    ///
    /// A number in the result that isn't finite becomes null.
    ///
    /// See `mln_style_expression_evaluate` in the
    /// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/style__expression_8h.html).
    ///
    /// Errors:
    ///
    /// - `error.InvalidArgument` when the expression fails to evaluate, such as
    ///   when it reads an input that `inputs` doesn't set.
    pub fn evaluate(self: StyleExpression, allocator: std.mem.Allocator, inputs: ?StyleExpressionInputs, diagnostic: ?*diagnostics.Diagnostic) status.Error!OwnedValue([]const u8) {
        return call.invoke("mln_style_expression_evaluate", .handle, self, allocator, diagnostic, .{ inputs, call.text(), call.textCapacity(), call.textLength() });
    }

    /// Reads what a style expression's result depends on.
    ///
    /// See `mln_style_expression_get_info` in the
    /// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/style__expression_8h.html).
    pub fn getInfo(self: StyleExpression, diagnostic: ?*diagnostics.Diagnostic) status.Error!StyleExpressionInfo {
        return call.invoke("mln_style_expression_get_info", .handle, self, null, diagnostic, .{call.sizedOut(StyleExpressionInfo)});
    }

    /// Releases a parsed style expression.
    ///
    /// See `mln_style_expression_release` in the
    /// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/style__expression_8h.html).
    pub fn release(self: *StyleExpression) void {
        if (self.closed) return;
        c.mln_style_expression_release(self.raw);
        self.closed = true;
    }
};

/// An action on a runtime's ambient cache.
///
/// The ambient cache holds the resources that maps load, apart from the ones
/// that offline regions hold.
///
/// See `mln_ambient_cache_operation` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/runtime_8h.html).
pub const AmbientCacheOperation = enum(u32) {
    /// Deletes the whole database, offline regions included, and starts an
    /// empty one.
    reset_database = 1,
    /// Shrinks the database file to free the disk space it no longer uses.
    pack_database = 2,
    /// Makes the library check each cached resource for changes before it uses
    /// the resource again.
    invalidate = 3,
    clear = 4,
    _,
    pub const fromNative = marshal.EnumMethods(@This()).fromNative;
    pub const toNative = marshal.EnumMethods(@This()).toNative;
};

/// How a camera change animates.
///
/// See `mln_animation_options` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/map_8h.html).
pub const AnimationOptions = struct {
    duration_ms: ?f64 = null,
    /// The average speed of a fly animation, in screens per second.
    /// `duration_ms` overrides it.
    velocity: ?f64 = null,
    /// The zoom level at the peak of a fly animation.
    min_zoom: ?f64 = null,
    easing: ?UnitBezier = null,
    /// An ID that `Map.cancelCameraTransition()` cancels the change by. Several
    /// changes can share one.
    transition_id: ?u64 = null,
    end_handler: CameraTransitionHandler = .{},
    pub fn toNative(self: AnimationOptions, roots: *callbacks.Roots) status.Error!c.mln_animation_options {
        var raw = std.mem.zeroes(c.mln_animation_options);
        raw.fields = 0;
        marshal.present(&raw.fields, c.MLN_ANIMATION_OPTION_DURATION, &raw.duration_ms, self.duration_ms);
        marshal.present(&raw.fields, c.MLN_ANIMATION_OPTION_VELOCITY, &raw.velocity, self.velocity);
        marshal.present(&raw.fields, c.MLN_ANIMATION_OPTION_MIN_ZOOM, &raw.min_zoom, self.min_zoom);
        marshal.present(&raw.fields, c.MLN_ANIMATION_OPTION_EASING, &raw.easing, self.easing);
        marshal.present(&raw.fields, c.MLN_ANIMATION_OPTION_TRANSITION_ID, &raw.transition_id, self.transition_id);
        raw.end_handler = try self.end_handler.toNative(roots);
        return raw;
    }

    pub fn fromNative(allocator: std.mem.Allocator, raw: c.mln_animation_options) status.Error!AnimationOptions {
        _ = allocator;
        return .{
            .duration_ms = if (raw.fields & c.MLN_ANIMATION_OPTION_DURATION != 0) raw.duration_ms else null,
            .velocity = if (raw.fields & c.MLN_ANIMATION_OPTION_VELOCITY != 0) raw.velocity else null,
            .min_zoom = if (raw.fields & c.MLN_ANIMATION_OPTION_MIN_ZOOM != 0) raw.min_zoom else null,
            .easing = if (raw.fields & c.MLN_ANIMATION_OPTION_EASING != 0) UnitBezier.fromNative(raw.easing) else null,
            .transition_id = if (raw.fields & c.MLN_ANIMATION_OPTION_TRANSITION_ID != 0) raw.transition_id else null,
            .end_handler = .{},
        };
    }
};

/// Limits on the camera, for `Map.setBounds()`.
///
/// See `mln_bound_options` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/map_8h.html).
pub const BoundOptions = struct {
    /// Removes the area that limits the camera's center.
    unbounded: bool = false,
    /// The area that the camera's center stays within.
    bounds: ?LatLngBounds = null,
    min_zoom: ?f64 = null,
    max_zoom: ?f64 = null,
    min_pitch: ?f64 = null,
    max_pitch: ?f64 = null,
    pub fn toNative(self: BoundOptions) c.mln_bound_options {
        var raw = std.mem.zeroes(c.mln_bound_options);
        raw.fields = 0;
        if (self.unbounded) raw.fields |= c.MLN_BOUND_OPTION_UNBOUNDED;
        raw.size = @sizeOf(c.mln_bound_options);
        marshal.present(&raw.fields, c.MLN_BOUND_OPTION_BOUNDS, &raw.bounds, self.bounds);
        marshal.present(&raw.fields, c.MLN_BOUND_OPTION_MIN_ZOOM, &raw.min_zoom, self.min_zoom);
        marshal.present(&raw.fields, c.MLN_BOUND_OPTION_MAX_ZOOM, &raw.max_zoom, self.max_zoom);
        marshal.present(&raw.fields, c.MLN_BOUND_OPTION_MIN_PITCH, &raw.min_pitch, self.min_pitch);
        marshal.present(&raw.fields, c.MLN_BOUND_OPTION_MAX_PITCH, &raw.max_pitch, self.max_pitch);
        return raw;
    }
    pub fn fromNative(raw: c.mln_bound_options) BoundOptions {
        return .{
            .unbounded = raw.fields & c.MLN_BOUND_OPTION_UNBOUNDED != 0,
            .bounds = if (raw.fields & c.MLN_BOUND_OPTION_BOUNDS != 0) LatLngBounds.fromNative(raw.bounds) else null,
            .min_zoom = if (raw.fields & c.MLN_BOUND_OPTION_MIN_ZOOM != 0) raw.min_zoom else null,
            .max_zoom = if (raw.fields & c.MLN_BOUND_OPTION_MAX_ZOOM != 0) raw.max_zoom else null,
            .min_pitch = if (raw.fields & c.MLN_BOUND_OPTION_MIN_PITCH != 0) raw.min_pitch else null,
            .max_pitch = if (raw.fields & c.MLN_BOUND_OPTION_MAX_PITCH != 0) raw.max_pitch else null,
        };
    }
};

/// A map's whole camera.
///
