pub const OpenGlBorrowedTexture = struct {
    /// Your texture name.
    texture: u32,
    pub fn toNative(self: OpenGlBorrowedTexture) c.mln_open_gl_borrowed_texture {
        var raw = std.mem.zeroes(c.mln_open_gl_borrowed_texture);
        raw.texture = self.texture;
