/// An image of 8-bit RGBA pixels whose colors are multiplied by their alpha.
///
/// See `mln_premultiplied_rgba8_image` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/style_8h.html).
pub const PremultipliedRgba8Image = struct {
    width: u32,
    height: u32,
    /// The number of bytes from the start of one row to the start of the next,
    /// at least `width` \* 4.
    stride: u32,
    /// The rows of pixels, `stride` bytes apart, from the top row down.
    pixels: []const u8,
    pub fn toNative(self: PremultipliedRgba8Image) status.Error!c.mln_premultiplied_rgba8_image {
        var raw = std.mem.zeroes(c.mln_premultiplied_rgba8_image);
        raw.size = @sizeOf(c.mln_premultiplied_rgba8_image);
        raw.width = self.width;
        raw.height = self.height;
        raw.stride = self.stride;
        raw.pixels = @ptrCast(self.pixels.ptr);
        raw.byte_length = std.math.cast(@TypeOf(raw.byte_length), self.pixels.len) orelse return error.InvalidArgument;
        return raw;
    }

    pub fn fromNative(allocator: std.mem.Allocator, raw: c.mln_premultiplied_rgba8_image) status.Error!PremultipliedRgba8Image {
        return .{
            .width = raw.width,
            .height = raw.height,
            .stride = raw.stride,
            .pixels = try marshal.copyView(allocator, .{ .data = raw.pixels, .size = raw.byte_length }),
        };
    }
};

