/// Options for a style image, as the
/// \[sprite\](https://maplibre.org/maplibre-style-spec/sprite/) spec describes
/// them.
///
/// See `mln_style_image_options` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/style_8h.html).
pub const StyleImageOptions = struct {
    /// The ranges of columns that stretch, in increasing order without overlap.
    stretch_x: ?[]const ImageStretch = null,
    /// The ranges of rows that stretch, in increasing order without overlap.
    stretch_y: ?[]const ImageStretch = null,
    content: ?ImageContent = null,
    text_fit_width: ?StyleImageTextFit = null,
    text_fit_height: ?StyleImageTextFit = null,
    pixel_ratio: ?f32 = null,
    sdf: ?bool = null,
    /// Keeps the image after no layer uses it. Without this, the map can remove
    /// an image that it asked for through
    /// `RuntimeEventType.map_style_image_missing`.
    keep_unused: ?bool = null,
    pub fn toNative(self: StyleImageOptions, allocator: std.mem.Allocator) status.Error!c.mln_style_image_options {
        var raw = std.mem.zeroes(c.mln_style_image_options);
        raw.fields = 0;
        raw.size = @sizeOf(c.mln_style_image_options);
        if (self.stretch_x) |item| {
            raw.fields |= c.MLN_STYLE_IMAGE_OPTION_STRETCH_X;
            raw.stretch_x = blk: {
                const items = try allocator.alloc(c.mln_image_stretch, item.len);
                for (item, 0..) |array_item_0, index| items[index] = array_item_0.toNative();
                break :blk items.ptr;
            };
        }
        raw.stretch_x_count = std.math.cast(@TypeOf(raw.stretch_x_count), if (self.stretch_x) |items| items.len else 0) orelse return error.InvalidArgument;
        if (self.stretch_y) |item| {
            raw.fields |= c.MLN_STYLE_IMAGE_OPTION_STRETCH_Y;
            raw.stretch_y = blk: {
                const items = try allocator.alloc(c.mln_image_stretch, item.len);
                for (item, 0..) |array_item_0, index| items[index] = array_item_0.toNative();
                break :blk items.ptr;
            };
        }
        raw.stretch_y_count = std.math.cast(@TypeOf(raw.stretch_y_count), if (self.stretch_y) |items| items.len else 0) orelse return error.InvalidArgument;
        marshal.present(&raw.fields, c.MLN_STYLE_IMAGE_OPTION_CONTENT, &raw.content, self.content);
        marshal.present(&raw.fields, c.MLN_STYLE_IMAGE_OPTION_TEXT_FIT_WIDTH, &raw.text_fit_width, self.text_fit_width);
        marshal.present(&raw.fields, c.MLN_STYLE_IMAGE_OPTION_TEXT_FIT_HEIGHT, &raw.text_fit_height, self.text_fit_height);
        marshal.present(&raw.fields, c.MLN_STYLE_IMAGE_OPTION_PIXEL_RATIO, &raw.pixel_ratio, self.pixel_ratio);
        marshal.present(&raw.fields, c.MLN_STYLE_IMAGE_OPTION_SDF, &raw.sdf, self.sdf);
        marshal.present(&raw.fields, c.MLN_STYLE_IMAGE_OPTION_KEEP_UNUSED, &raw.keep_unused, self.keep_unused);
        return raw;
    }

    pub fn fromNative(allocator: std.mem.Allocator, raw: c.mln_style_image_options) status.Error!StyleImageOptions {
        return .{
            .stretch_x = if (raw.fields & c.MLN_STYLE_IMAGE_OPTION_STRETCH_X != 0) blk: {
                const copied = try allocator.alloc(ImageStretch, raw.stretch_x_count);
                for (try marshal.nativeSlice(c.mln_image_stretch, raw.stretch_x, raw.stretch_x_count), 0..) |item, index| copied[index] = ImageStretch.fromNative(item);
                break :blk copied;
            } else null,
            .stretch_y = if (raw.fields & c.MLN_STYLE_IMAGE_OPTION_STRETCH_Y != 0) blk: {
                const copied = try allocator.alloc(ImageStretch, raw.stretch_y_count);
                for (try marshal.nativeSlice(c.mln_image_stretch, raw.stretch_y, raw.stretch_y_count), 0..) |item, index| copied[index] = ImageStretch.fromNative(item);
                break :blk copied;
            } else null,
            .content = if (raw.fields & c.MLN_STYLE_IMAGE_OPTION_CONTENT != 0) ImageContent.fromNative(raw.content) else null,
            .text_fit_width = if (raw.fields & c.MLN_STYLE_IMAGE_OPTION_TEXT_FIT_WIDTH != 0) StyleImageTextFit.fromNative(raw.text_fit_width) else null,
            .text_fit_height = if (raw.fields & c.MLN_STYLE_IMAGE_OPTION_TEXT_FIT_HEIGHT != 0) StyleImageTextFit.fromNative(raw.text_fit_height) else null,
            .pixel_ratio = if (raw.fields & c.MLN_STYLE_IMAGE_OPTION_PIXEL_RATIO != 0) raw.pixel_ratio else null,
            .sdf = if (raw.fields & c.MLN_STYLE_IMAGE_OPTION_SDF != 0) raw.sdf else null,
            .keep_unused = if (raw.fields & c.MLN_STYLE_IMAGE_OPTION_KEEP_UNUSED != 0) raw.keep_unused else null,
