/// A callback that tells the caller when work is ready.
///
/// Can run on any thread, including the caller's own thread during a library
/// call. Return quickly and don't block.
///
/// See `mln_wake` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/wake_8h.html).
pub const Wake = struct {
    context: ?*anyopaque = null,
    release_context: ?*const fn (?*anyopaque) void = null,
    callback: ?*const fn (context: ?*anyopaque) anyerror!void = null,
    pub fn toNative(self: Wake, roots: *callbacks.Roots) status.Error!c.mln_wake {
        var raw = std.mem.zeroes(c.mln_wake);
        raw.callback = if (self.callback != null) callbackTrampoline else null;
        if (!(self.callback == null)) {
            const retained = try roots.retain(Wake, self);
            raw.user_data = retained;
            raw.release_user_data = callbacks.Registration(Wake).releaseNative;
        }
        return raw;
    }
    fn callbackTrampoline(native_arg_0: marshal.CallbackArg(c.mln_wake_callback, 0)) callconv(.c) marshal.CallbackResult(c.mln_wake_callback) {
        return struct {
            fn invoke(callback_arg_0: marshal.CallbackArg(c.mln_wake_callback, 0)) anyerror!marshal.CallbackResult(c.mln_wake_callback) {
                const state = callbacks.Registration(Wake).get(callback_arg_0);
                const host = state.value.callback orelse {
                    return;
                };
                try host(state.value.context);
            }
        }.invoke(native_arg_0) catch |err| {
            callbacks.reportError("mln_wake_callback", err);
            return;
        };
    }
    /// Builds a `Wake` whose callbacks receive `context`, a pointer, as
    /// its own type. Each callback takes the context and then the arguments
    /// of its field, and may return any error; pass null to leave one unset.
    /// Native runs `release`, when it is not null, once it releases the
    /// registration.
    pub fn init(context: anytype, comptime callback: anytype, comptime release: ?fn (@TypeOf(context)) void) Wake {
        const Context = @TypeOf(context);
        if (@typeInfo(Context) != .pointer) @compileError("a Wake context must be a pointer");
        return .{
            .context = @ptrCast(@constCast(context)),
            .release_context = if (release == null) null else struct {
                fn call(erased: ?*anyopaque) void {
                    release.?(@as(Context, @ptrCast(@alignCast(erased.?))));
                }
            }.call,
            .callback = if (@TypeOf(callback) == @TypeOf(null)) null else struct {
                fn call(erased: ?*anyopaque) anyerror!void {
                    return callback(@as(Context, @ptrCast(@alignCast(erased.?))));
                }
            }.call,
        };
    }
};

/// The WebGL context or canvas that a render session uses.
